import assert from 'node:assert/strict';
import {scan} from './fisica-janelas-saltos.js';
import {getApproachJumpSpeed,createBabyState} from '../../../src/js/config.js';
const results=[];
for(const phase3 of [false,true])for(const difficulty of ['NORMAL','EASY'])for(const dt of [.5,1,1.2]) {
 const rows=[];
 for(let target=0;target<(phase3?16:10);target++) {
  const result=scan(target,phase3,undefined,dt,difficulty);assert.ok(result.count>=8,'Saídas viáveis para alvo '+target);
  rows.push({target,...result,ms:Math.round(result.ms)});
 }
 if(difficulty==='NORMAL') {
  if(phase3)assert.ok(rows.every(row=>row.ms>0),'Todos os apoios do retorno oferecem saída viável');
  else {
   assert.ok(rows[0].ms>1000&&rows[1].ms>750,'Dois primeiros saltos continuam generosos');
   for(let index=-1;index<9;index++)assert.ok(getApproachJumpSpeed(index)>=createBabyState().baseVx,'Aproximação não pode criar frenagem aérea para estreitar janelas');
  }
 }
 results.push({phase3,difficulty,dt,rows});
}
console.log(JSON.stringify(results,null,2));console.log('APROVADO: aproximação sem frenagem artificial e progressão pós-clímax; 26 saltos, NORMAL/EASY e três passos de tempo.');
